// === Tab: Face ===
const Dir = {
	Forward: 'Forward',
	Left: 'Left',
	Right: 'Right',
	Up: 'Up',
	Down: 'Down'
};
const State = {
	Looking: 'Looking',
	Changing: 'Changing',
	Blinking: 'Blinking',
};

class Face {
	constructor(_x, _y, _w) {
		this.x = _x; // position x
		this.y = _y; // velocity y
		this.w = _w; // width
		this.happiness = 30; // 0=Unhappy, 30=OK, >80=blushing, 100=elated
		this.headscale = random(0.9, 1.05);
		this.headshape = random(0.8, 1.2);
		this.rot = random(-0.25, 0.25); //stroke rotation
		this.state = State.Looking;
		var newdir = floor(random(5));
		if (newdir == 0) this.dir = Dir.Forward;
		else if (newdir == 1) this.dir = Dir.Left;
		else if (newdir == 2) this.dir = Dir.Right;
		else if (newdir == 3) this.dir = Dir.Up;
		else if (newdir == 4) this.dir = Dir.Down;
		this.lookat = look(this.dir).copy();
		this.oldlookat = look(this.dir).copy();
		this.nextlookat = look(this.dir).copy();
		this.looksweep = 0; //animation
		this.blinksweep = 0; //animation
		this.contact = false; // made eye contact

		this.f1 = freq1[floor(random(freq1.length))];  // Note to self - or just this.f1 = random(freq1);
		this.f2 = freq2[floor(random(freq2.length))];

		this.osc = new p5.Oscillator('sine');
		this.osc.start();
		this.osc.freq(this.f1); // major chords
		this.osc.amp(0);
		this.osc.pan(map(this.x,0,xCount-1,-1,1));
	}

	// Check for Eye Contact
	check_contact() {
		this.contact = false;
		if (this.x > 0 && this.dir == 'Left' && Faces[this.x - 1 + this.y * xCount].dir == 'Right' && Faces[this.x - 1 + this.y * xCount].state != 'Changing') {
			this.contact = this.contact || true;
		}
		if (this.x < xCount - 1 && this.dir == 'Right' && Faces[this.x + 1 + this.y * xCount].dir == 'Left' && Faces[this.x + 1 + this.y * xCount].state != 'Changing') {
			this.contact = this.contact || true;
		}
		if (this.y > 0 && this.dir == 'Up' && Faces[this.x + (this.y - 1) * xCount].dir == 'Down' && Faces[this.x + (this.y - 1) * xCount].state != 'Changing') {
			this.contact = this.contact || true;
		}
		if (this.y < yCount - 1 && this.dir == 'Down' && Faces[this.x + (this.y + 1) * xCount].dir == 'Up' && Faces[this.x + (this.y + 1) * xCount].state != 'Changing') {
			this.contact = this.contact || true;
		}
	}

	// Main State Logic
	update() {
		switch (this.state) {
			case 'Looking':
				this.check_contact(); //check for eye contact

				var lookaway = 0; //probability
				if (avoidEyeContact) {
					lookaway = 0.002; //no eye contact
					if (this.contact) {
						lookaway = 0.1; //avoid eye contact
					}
				}
				if (!avoidEyeContact) {
					lookaway = 0.005; //no eye contact
					if (this.contact) {
						lookaway = 0.0005; //keep eye contact
					}
				}

				if (random(1) < lookaway) { // start changing direction
					this.state = State.Changing;
					var tempdir = this.dir;
					let _wG_1 = 0; while ((tempdir == this.dir) && ++_wG_1 < 20000) { //make sure its different
						var newdir = floor(random(5));
						if (newdir == 0) this.dir = Dir.Forward;
						else if (newdir == 1) this.dir = Dir.Left;
						else if (newdir == 2) this.dir = Dir.Right;
						else if (newdir == 3) this.dir = Dir.Up;
						else if (newdir == 4) this.dir = Dir.Down;
					}
					this.nextlookat = look(this.dir).copy();
					this.oldlookat = this.lookat.copy();
				}

				if (random(1) < 0.001) { // start blink
					this.state = State.Blinking;
				}

				break;

			case 'Changing':
				if (this.looksweep <= 1) { // lerp the eye position
					this.lookat = p5.Vector.lerp(this.oldlookat, this.nextlookat, this.looksweep);
					this.looksweep += 0.05;
				} else { //done moving
					this.state = State.Looking;
					this.lookat = this.nextlookat.copy();
					this.oldlookat = this.lookat.copy();
					this.nextlookat = this.lookat.copy();
					this.looksweep = 0;
				}
				break;

			case 'Blinking':
				if (this.blinksweep > 1) {
					this.state = State.Looking;
					this.blinksweep = 0;
				} else {
					this.blinksweep += 0.2;
				}
				break;

		}

		//update happiness
		if (avoidEyeContact) {
			if (this.contact) { // contact made
				this.happiness = 0;
			} else {
				this.happiness = min(30, this.happiness + 0.2);
			}
			this.osc.setType('square');
			this.osc.freq(this.f2*random(0.95,1.05)); // minor chords
			this.osc.amp(sq(map(this.happiness,0,30,0.3,0)));
		}
		if (!avoidEyeContact) {
			if (this.contact) { //contact made
				this.happiness = min(100, this.happiness + 0.2);
			} else {
				this.happiness = max(30, this.happiness - 0.2);
			}
			this.osc.setType('sine');
			this.osc.freq(this.f1); // major chords
			this.osc.amp(sq(map(this.happiness,30,100,0,0.2)));
		}
	}

  //Draw the face
	display() {
		// locate position and scale.  Drawing is all in (-1..1,-1..1)
		push();
		noStroke();
		translate(this.x * cellSize, this.y * cellSize);
		scale(this.w * this.headscale, this.w);

		// rotating happy strokes
		if (this.happiness == 100) {
			push();
			noFill();
			stroke(inkColor);
			strokeWeight(0.02);
			var dir = ((this.x % 2 + this.y % 2) % 2) * 2 - 1
			rotate(dir * frameCount / 100);
			for (let i = 0; i < 36; i++) {
				line(0.55, 0, 0.62, 0);
				rotate(TAU / 36);
			}
			pop();
		}

		// head
		fill(inkColor);
		dbc(0, 0, 1.03, 3, this.headshape, PI / 6 + this.rot, 0);
		fill((this.happiness < 10) ? scaredColor : bgColor);  //cool inline conditional
		dbc(0, 0, 1.0, 3, this.headshape, PI / 6, 0);

		//mouth
		if (avoidEyeContact) { 
			if (this.happiness < 10) { // scared mouth
				fill(inkColor);
				ellipse(0, 0.3, 0.2, 0.2);
			} else { //resting mouth
				push()
				rotate(-this.rot/2);
				fill(inkColor);
				ellipse(0, 0.35, 0.25, 0.03);
				pop();
			}
		}

		if (!avoidEyeContact) {
			if (this.contact) {
				fill(inkColor);
				ellipse(0, 0.2, map(this.happiness, 30, 100, 0.2, 0.5), 0.4); // growing smile
				fill(bgColor);
				ellipse(0, 0.10, 0.7, map(this.happiness, 30, 100, 0.55, 0.25)); // growing smile
				if (this.happiness > 80) {
					//blush spots
					fill(0, 100, 100, 3);
					for (let i = 1; i < 5; i++) {
						ellipse(0.3, 0.2, i / 20, i / 20);
						ellipse(-0.3, 0.2, i / 20, i / 20);
					}
				}
			} else { // resting mouth
				push()
				rotate(-this.rot/2);
				fill(inkColor);
				ellipse(0, 0.35, 0.15, 0.05);
				pop();
			}
		}

		// eyes
		var offset = 0.22; //eye offset
		for (let i = -1; i <= 1; i += 2) {
			push();
			translate(i * offset, -0.05);
			if (i == -1) scale(this.headscale);  //make left eye bigger or smaller
			if (avoidEyeContact) { //scared eyes quiver
				translate(random(-0.01, 0.01), random(-0.01, 0.01));
				if (this.happiness < 10) {  //real scared eyes scale up
					scale(1.25);
				}
			}

			//eyeball
			push();
			fill(inkColor);
			rotate(this.rot);
			ellipse(0, 0, 0.34, 0.42);
			pop();
			fill(255);
			ellipse(0, 0, 0.3, 0.4);

			//pupil
			push();
			translate(this.lookat.x, this.lookat.y)  // eye motion animation
			fill(inkColor);
			ellipse(0, 0, 0.21, 0.2);
			fill(255);
			ellipse(0.04, -0.04, 0.06, 0.06);  //highlight
      pop();

			//eyelid covers the entire eye all at once
			if (this.state == 'Blinking') {
				fill((this.happiness < 10) ? scaredColor : bgColor); //cool inline conditional
				ellipse(0, 0, 0.4, 0.45);
			}
			pop();
		}
		pop();
	}
}

// helper function turns the direction into a PVector
function look(dir) {
	result = createVector(0, 0);
	switch (dir) {
		case 'Right':
			result.set(0.045, 0);
			break;
		case 'Left':
			result.set(-0.045, 0);
			break;
		case 'Up':
			result.set(0, -0.08);
			break;
		case 'Down':
			result.set(0, 0.08);
			break;
		default:
			break;
	}
	return (result);
}

// draws smoothed n-gons with bezier curves - used for the head
function dbc(centerX, centerY, rad, segments, c_mult, rot, noiseval) {
	if (segments < 2) {
		segments = 2;
	}

	var origin = createVector(centerX, centerY);
	var start = createVector(rad / 2 + randomGaussian() * noiseval, randomGaussian() * noiseval);
	var start_copy = createVector(0, 0);
	var end = createVector(0, 0);
	var end_copy = createVector(0, 0);
	var c_offset = createVector(0, 0);
	var c1 = createVector(0, 0);
	var c2 = createVector(0, 0);

	start_copy.set(start);

	start.rotate(rot);
	start.add(origin);

	beginShape();
	vertex(start.x, start.y);

	for (let segment = 0; segment < segments - 1; segment++) {
		end = createVector(rad / 2 + randomGaussian() * noiseval, randomGaussian() * noiseval);

		c_offset = createVector(0, c_mult * (rad / 2.0) * (4.0 / 3.0) * tan(PI / (2 * segments)) + randomGaussian() * noiseval);
		end_copy.set(end);

		end.rotate(rot + (segment + 1) * TWO_PI / segments);
		end.add(origin);

		c1.set(end_copy);
		c1.add(c_offset);
		c1.rotate(rot + segment * TWO_PI / segments);
		c1.add(origin);

		c2.set(end_copy);
		c2.sub(c_offset);
		c2.rotate(rot + (segment + 1) * TWO_PI / segments);
		c2.add(origin);

		bezierVertex(c1.x, c1.y, c2.x, c2.y, end.x, end.y);
	}

	c1.set(start_copy);
	c1.add(c_offset);
	c1.rotate(rot + (segments - 1) * TWO_PI / segments);
	c1.add(origin);

	c2.set(start_copy);
	c2.sub(c_offset);
	c2.rotate(rot);
	c2.add(origin);

	bezierVertex(c1.x, c1.y, c2.x, c2.y, start.x, start.y);

	endShape();
}

