var Faces = [];

var xCount = 13; //    <<<====== Change this for the number of faces in X   <<<<<=====
var yCount = 7;  //    <<<====== or this for the number of faces in Y       <<<<<=====

var cellSize;
var xOff;
var yOff;
var avoidEyeContact;
var bgColor = [45, 12.9, 94.5];
var scaredColor = [45, 10, 90];
var inkColor = [45, 40, 20];

var freq1 = [];  //major scale
var freq2 = [];  //minot scale

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	background(bgColor);
	smooth();

	cellSize = min(width / xCount, height / yCount);
	xOff = cellSize / 2 + (width - cellSize * xCount) / 2;
	yOff = cellSize / 2 + (height - cellSize * yCount) / 2;

  //build notes
	for (let i = 1; i<5; i++) {   // Major 7th 8:10:12:15
		freq1.push(i*220*8/8);
		freq1.push(i*220*10/8);
		freq1.push(i*220*12/8);
		freq1.push(i*220*15/8);
	}
	for (let i = 1; i<6; i++) {   // Dim 160:192:231
		freq2.push(i*220*160/160);
		freq2.push(i*220*192/160);
		freq2.push(i*220*231/160);
	}


	var faceSize = 0.8 * cellSize;

	for (let y = 0; y < yCount; y++) {
		for (let x = 0; x < xCount; x++) {
			Faces.push(new Face(x, y, faceSize));
		}
	}	
}

function draw() {
	background(bgColor);
	avoidEyeContact = (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) === true);

	translate(xOff, yOff);
	for (let i = 0; i < Faces.length; i++) {
		Faces[i].update();
		Faces[i].display();
	}
}

